export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertCanManageAbsence(actor, member);

  await memberRepo.deleteAbsence(orgId, userId);
}

/** The stored absence until it has ended — including one not yet started. */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertCan(actor, "member:read", memberResource(member));

  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence || Date.parse(absence.endsAt) <= Date.now()) return null;
  return absence;
}

/**
 * Who stands in for `userId` at instant `at`: the delegate of an absence that
 * has started and not yet ended, provided the delegate is still an active
 * member. `null` means "nobody — the user handles it themselves". Never
 * chained: the delegate's own absence is not consulted.
 */
export async function findStandIn(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence || absence.delegateUserId === null) return null;
  if (!isAbsenceActive(absence, at)) return null;

  const delegate = await memberRepo.findMember(orgId, absence.delegateUserId);
  if (!delegate || delegate.status !== "active") return null;

  return absence.delegateUserId;
}

/** `[startsAt, endsAt)` — the start counts, the end does not. */
function isAbsenceActive(absence: MemberAbsence, at: Date): boolean {
  const now = at.getTime();
  return (
    Date.parse(absence.startsAt) <= now && now < Date.parse(absence.endsAt)
  );
}

async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

function assertCanManageAbsence(actor: Actor, member: Member): void {
  if (member.userId === actor.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

